import {g} from './shared.js';
export const sequenceGuides=[
g('transformer','处理序列时，某个位置需要从其他位置获取信息。Transformer 用注意力进行位置间交互，再用逐位置网络加工表示，形成可堆叠的计算骨干。',
 ['读“杯子放在桌上，它是红色的”时，要判断“它”关联谁；需要在候选上下文之间建立关系。','注意力是数值加权，不代表模型具有人的阅读意图或可靠指代理解。'],
 ['每个 token 先有向量和位置信息。','注意力混合允许读取的位置；FFN 再变换每个位置的特征，残差和归一化帮助堆叠。','输出头把最后表示变为类别或 token 分数；训练目标另行指定。'],
 ['先定义输入形状、位置规则与 mask。','追踪 attention、FFN、残差、归一化和头的接口。','用因果测试、梯度检查和小任务验证再扩层。'],
 '灵活组织上下文交互，训练时能并行处理已知序列位置。','全注意力随长度成本增长，需要数据、位置机制与正确 mask；Transformer 不是特定训练阶段。',
 ['Transformer 必须做语言 next-token 训练吗？','不是，它可以用于视觉、扩散、状态预测等不同目标。']),
g('encoder-decoder','有些任务输入和输出的结构、长度不同，既要充分理解整个输入，又要逐步生成输出。编码器—解码器将输入表示与输出生成分工。',
 ['翻译者先读完整个待译段落，再逐句写译文，同时反复回看原文。','真实模型是通过 self/cross attention 计算；并不一定先形成完整人类式理解。'],
 ['编码器处理原句“我 爱 猫”的全部可用内容。','解码器生成“I”后，读取已生成前缀和编码器表示来预测“love”。','cross attention 连接输入与输出，不能和解码器内部因果 attention 混为一谈。'],
 ['明确 encoder 输入、decoder 输入和目标 shift。','分别设置输入 padding、输出因果和交叉读取规则。','比较任务效果和双模块成本。'],
 '适合明确的输入→输出变换，输入可双向编码并供多步生成复用。','模块与缓存更复杂，未必比单流骨干更划算；要按任务测，而非认定结构天然更聪明。',
 ['cross attention 的 K/V 必须来自已生成 token 吗？','不必，在典型 encoder-decoder 中来自编码器输出。']),
g('decoder-only','如果任务主要是根据前缀续写，可以把输入条件和输出放进同一序列，用因果骨干建模，不另设一个独立输入编码器。',
 ['按顺序填一条不断延长的记录，每次只能看已经写好的部分。','“only”不表示模型内部只有一个层或没有视觉编码器；完整多模态系统仍可外挂视觉塔。'],
 ['序列为“问题…回答：…”，预测位置只能读取允许的前缀。','训练时对多个目标位置并行求 loss；推理通常逐 token 延长序列。','是否用 SFT、LoRA 或某种注意力，是另外的选择。'],
 ['画出条件与输出拼接、特殊 token 和监督区域。','验证未来 token 改动不影响此前位置输出。','检查推理 KV cache 与训练的完整前向是否一致。'],
 '统一续写接口，便于复用语言基座和自回归生成流程。','生成存在串行步骤，长上下文可能昂贵；名字不能证明完整世界模型或机器人能力。',
 ['Decoder-only 与 AR 完全同义吗？','不是。一个描述骨干组织，一个描述概率分解/生成方式；它们常组合但不等同。']),
g('attention','只把当前词独立映射为输出，会缺少上下文；把所有历史简单平均又无法因问题不同而选择重点。Attention 用当前 query 对候选 key 评分，再混合 value。',
 ['找餐厅时，用“便宜且近”作为查询，比较每家店的索引信息，再汇总相关介绍。换成“适合聚餐”，权重会改变。','它不会自动判断资料真伪；高权重也不是严格的因果解释。'],
 ['两个候选分数为 [0,ln3]，softmax 权重为 [0.25,0.75]。','value 为 [2,10]，输出=0.25×2+0.75×10=8。','若第二位置被 mask，重新归一后输出为 2，而不是仍乘旧权重。'],
 ['写清 Q/K/V 来源与维度。','先应用可见性限制，再稳定归一化分数。','用手算、padding、因果和空可见集合测试验证。'],
 '可依当前内容动态选择上下文，比固定平均更灵活。','全连接读写成本随长度增加；错误 mask 会泄漏未来，权重图不能单独证明推理依据。',
 ['把一个 key 隐藏后，其余权重通常要重新归一吗？','要，否则加权输出不再遵循原本的 softmax 可见集合。']),
g('causal-mask','预测下一项时，训练代码同时持有整条真实序列。若模型偷看未来，训练成绩会很高，部署却拿不到这些信息。因果 mask 限制前向读取。',
 ['考试时把答案纸遮住；不是把答案算错时不扣分，而是根本不能看答案。','这对应可见性，不对应 loss 计分范围。'],
 ['三位置的允许矩阵为 [[1,0,0],[1,1,0],[1,1,1]]。','第 2 个位置可看第 1/2 个，不能看第 3 个。','改变未来 token，前面输出应保持不变；再叠加 padding 屏蔽。'],
 ['确认框架 mask 中 True 表示允许还是禁止。','对齐 query/key 的真实位置，特别是 cache 场景。','执行未来扰动测试，而不只目测三角矩阵。'],
 '使训练信息约束与自回归部署一致，防止一种直接标签泄漏。','因果约束限制双向理解；缓存、窗口和 padding 混用时容易偏一位。',
 ['mask 数值 1 在所有库里都表示可见吗？','不是，不同 API 语义不同，必须读接口并测试。']),
g('position','如果只看 token 内容，不提供顺序信息，很多交互会难以区分词序。位置机制让“猫追狗”和“狗追猫”的顺序进入计算。',
 ['同样三个物品摆在不同格子，格号帮助区分排列；但格号不是物品本身。','位置编码有绝对、相对、旋转等不同设计，不都等于给向量加一个编号。'],
 ['句子内容向量相同，位置 0/1 的角色可能不同。','某些方式把位置向量加入表示，RoPE 类方式旋转 Q/K 以影响相对关系。','把窗口拉长后，模型是否仍会用位置，必须通过远距离任务测试。'],
 ['识别所用位置方案与训练长度。','检查 cache offset、packing 边界和重置规则。','比较长度和证据位置变化，不只看能否接受长输入。'],
 '使顺序和距离信息参与建模，可设计不同长度偏好。','长度外推、缩放与边界处理可能出错；改配置上限不自动获得长文本能力。',
 ['输入顺序颠倒而输出不变，一定是位置编码坏了吗？','不一定，任务、数据或模型忽略信息也可能导致；需要针对性对照。']),
g('moe','把每个 token 都送入很大的 FFN，成本可能太高。MoE 用路由器为不同输入选择少数专家，增加总容量而不每次激活全部参数。',
 ['医院按情况分诊给少数专科，而不是每位病人都让所有医生重复检查。','专家不保证自动形成可命名的人类专业，路由也可能偏向少数模块。'],
 ['4 个专家，某 token 的路由分数选中专家 1 和 3。','只计算选中专家并按权重组合；总专家参数与该 token 激活参数不同。','若所有 token 挤到同一专家，会产生负载和学习问题。'],
 ['记录专家数、top-k、容量与路由/负载目标。','统计专家使用量、丢弃/溢出和跨卡通信。','在固定预算下比较质量与实测吞吐。'],
 '提供条件计算，可用较小的每 token 激活成本利用较大总容量。','路由、负载和通信复杂；总参数大不代表单次计算量等比例大，也不保证更快。',
 ['8 个专家、每次选 2 个，是否只需存储 2 个专家？','一般不能这样推断，系统仍需管理全部专家权重和部署分布。']),
g('linear-attention','全注意力要形成大量位置对。某些线性注意力重排计算，用可累积状态表示历史，使成本对序列长度更有利。',
 ['反复问“到目前为止总收入多少”，可以维护累计账本，而不是每次重读全部流水。','摘要保存了什么由具体形式决定，不能假装完整保留每一笔细节。'],
 ['一种核形式维护 S=Σφ(k)vᵀ 及归一化量 z=Σφ(k)。','当前 query 用 φ(q) 读取 S，并在该形式中除以相应分母。','它通常不与原始 softmax attention 完全等价；带 delta/gate 的状态路线又有不同更新。'],
 ['确认具体公式，别只凭“linear”名字实现。','检查整段与递推读取、归一化和数值稳定性。','比较长序列质量、状态大小与硬件耗时。'],
 '某些形式支持固定状态与更低长度增长成本，适合流式处理。','状态压缩有表达限制，数值与 kernel 决定实测效果；线性长度成本不等于线性模型。',
 ['Linear attention 表示网络只能表达直线关系吗？','不是，linear 通常指某种复杂度或计算形式，整个网络仍可非线性。']),
g('kda','历史摘要既要保留旧信息，也要纠正旧记忆。KDA 在 delta 状态更新路线中使用更细粒度门控，让有限状态的保留与修正更灵活。',
 ['账本里某个商品价格过时，只改相应关联，比把整本账本同程度遗忘更有针对性。','这种类比不是 KDA 的完整矩阵算法，不能把一个标量账本叫完整 KDA。'],
 ['先看简化 delta 直觉：旧预测为 0.2，新目标 0.8，差值 0.6。','更新强度 0.5 时，沿该关联修正 0.3；矩阵形式还涉及 key/value 与状态方向。','KDA 的细粒度门控与分块计算需按原论文实现；Kimi Linear 是包含其他层的混合整体。'],
 ['先区分完整模型、KDA 模块与教学 delta 核心。','核对状态维度、门控、分块和 reset/detach。','与相同输入的全注意力/其他状态路线比较质量与实测资源。'],
 '可在有限状态中更有选择地管理历史，并利用专门分块实现。','压缩记忆仍有信息限制，实现与数值要求高；论文某设置的速度不能直接外推到本机。',
 ['做出 scalar delta 更新就复现 Kimi Linear 了吗？','没有，它只解释记忆修正的一部分，完整门控、骨干、训练与 kernel 都还需要实现。']),
g('ssm','长序列若每步重新读取全部历史会很贵。状态空间模型用状态转移描述历史如何保留、输入如何写入、输出如何读出；现代序列模型在此基础上加入不同参数化。',
 ['房间温度由昨天的热量保留和今天暖气输入共同决定；读数通过状态随时间变化。','学习式 SSM 的状态未必对应真实物理量，Mamba 等也不能简化为一个固定系数公式。'],
 ['简化离散 SSM：s_t=0.8s_(t-1)+x_t，y_t=s_t。','s0=0，输入 [1,0,0]，输出 [1,0.8,0.64]，展示衰减记忆。','系数若大于 1 可能放大；选择性模型还让部分参数随输入改变。'],
 ['写清状态/输入/输出接口和离散化约定。','用脉冲、整段/分块和 reset 测试观察记忆。','针对远距检索与流式任务比较质量、数值和速度。'],
 '可通过紧凑状态处理很长序列，适合研究记忆与动态响应。','有限状态可能丢精确细节，稳定性和实现重要；SSM、S4、Mamba 不是同一个公式。',
 ['状态固定大小，是否能无损记住无限长输入？','不能据此推断，固定容量通常意味着压缩和任务相关的信息取舍。']),
g('ar','一个输出序列可能很长且内部相关。自回归把联合概率分成一串“给定此前内容预测下一项”的条件概率，便于训练和逐步采样。',
 ['按已有旋律接下一个音，比同时决定整首乐曲的所有位置更容易组织；早先音符也会限制后续选择。','AR 是依赖分解，不只用于文字，也不指定一定要 Transformer。'],
 ['P(a,b,c)=P(a)P(b|a)P(c|a,b)。','训练可利用已知真实前缀计算多位置目标。','生成时先采 a，再采 b；第一步错了，后面条件随之改变。'],
 ['定义序列化顺序、token/动作表示和停止规则。','核对因果可见性及训练目标对齐。','评估自由生成质量、误差累积与串行成本。'],
 '把复杂序列概率拆成可复用的下一步预测，能灵活生成可变长度。','推理通常串行，顺序设计与暴露偏差影响质量；图像的离散 AR 与去噪生成是不同路线。',
 ['训练一次算多个位置就不是 AR 了吗？','仍可以是 AR，关键是条件分解和可见信息，不是训练循环是否逐位置执行。'])
];
